--
-- 為什麼把 6811 筆資料塞進 migration 而不是在 prod 重跑一次 LLM：
-- 諧音是溫度 0.9 生成的，重跑一定長得不一樣，local 驗過的品質不會複製到 prod。
-- 把 local 跑完並人工抽樣過的結果當成事實來源送上去，兩邊才會一致。
