--
-- 只覆蓋 quality < 2：2 = 人工確認過，那是比機器產出更高的權威，不能被這支蓋掉。
update public.dict_cache d set
  senses     = v.senses,
  core_sense = v.core_sense,
  mnemonic   = v.mnemonic,
  quality    = v.quality,
  stages     = v.stages
